import { ActionEditorTab } from './action_editor_tab'
import { ActionPhraseToolbarControls } from './action_phrase_toolbar_controls'
import { actionPhraseLabel } from './action_phrase_label'
import { ACTION_DEFINITION_TAB, useActionEditorController } from './use_action_editor_controller'

interface ActionEditorNavigationProps {
    action: ActionDefinition
    discardMarkdownTarget: (target: MarkdownDocumentTarget) => void
    openDocument: ActionOpenDocument
    onMarkdownPresentationChange: (presentation: ActionMarkdownPresentation | null) => void
    sourcePath: string
}

/** Tabs and Markdown binding backed directly by ActionService controller. */
export function ActionEditorNavigation(props: ActionEditorNavigationProps) {
    const { action, discardMarkdownTarget, openDocument, onMarkdownPresentationChange, sourcePath } = props
    const actions = actionService.getActions()
    const controller = useActionEditorController({ action, actions, discardMarkdownTarget, openDocument, sourcePath })
    const {
        activeTab, definition, errors, handleDeletePhrase, handlePhraseTitleCommit, handlePhraseTitleEdit,
        handleTabChange, markdownTarget, phraseEditorStates, phrases, selectedPhrase, validation,
    } = controller

    const phraseToolbarContents = useCallback(() => {
        if (!selectedPhrase) return null

        return (
            <ActionPhraseToolbarControls
                onDelete={handleDeletePhrase}
                onTitleCommit={handlePhraseTitleCommit}
                onTitleEdit={handlePhraseTitleEdit}
                title={selectedPhrase.title}
            />
        )
    }, [handleDeletePhrase, handlePhraseTitleCommit, handlePhraseTitleEdit, selectedPhrase])

    useEffect(() => {
        const target = definition.type === 'agent' && activeTab !== ACTION_DEFINITION_TAB ? markdownTarget : null
        actionMarkdownDataSource.setActiveActionTarget(target)
        onMarkdownPresentationChange(target ? {
            placeholders: selectedPhrase ? undefined : ACTION_PROMPT_PLACEHOLDERS,
            toolbarContents: selectedPhrase ? phraseToolbarContents : undefined,
        } : null)
    }, [activeTab, definition.type, markdownTarget,
        onMarkdownPresentationChange, phraseToolbarContents, selectedPhrase])

    useEffect(() => () => {
        actionMarkdownDataSource.setActiveActionTarget(null)
        onMarkdownPresentationChange(null)
    }, [onMarkdownPresentationChange])

    if (definition.type !== 'agent') return null
    const definitionError = validation.error && validation.field !== 'prompt' && validation.field !== 'phrases'
        ? validation.error
        : undefined
    const phraseErrorIndex = validation.field === 'phrases' ? validation.index : null

    return (
        <Tabs aria-label="Action editor sections" onChange={handleTabChange} scrollButtons="auto" sx={{ borderTop: 1, borderColor: 'divider', flexShrink: 0, order: 2 }} value={activeTab} variant="scrollable">
            <ActionEditorTab error={definitionError} label="Definition" value={ACTION_DEFINITION_TAB} />
            <ActionEditorTab error={errors.prompt} label="Prompt" value="prompt" />
            {phrases.map((phrase, index) => (
                <ActionEditorTab
                    error={phraseErrorIndex === index ? errors.phrases : undefined}
                    key={phraseEditorStates[index].identity}
                    label={actionPhraseLabel(phrase.title, phrase.text)}
                    value={phraseEditorStates[index].identity}
                />
            ))}
            <Tab aria-label="Add predefined phrase" label="+" value="add-phrase" />
        </Tabs>
    )
}

import type { ActionEditorState, RawActionDefinition } from '../../data/action_types'
import type { ActionService } from '../../services/actions/action_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService, type OpenDocumentChangedDetail } from '../../services/open_files_service'
import {
    MarkdownDataSourceBase,
    type ActionMarkdownSection,
    type MarkdownBindingKind,
    type MarkdownDocumentTarget,
} from './markdown_data_source'

type ActionMarkdownTarget = Extract<MarkdownDocumentTarget, { section: ActionMarkdownSection }>

type ActionMarkdownOwner = EventTarget & Pick<ActionService, 'draftStore' | 'setActionEditorState'>

function actionTarget(target: MarkdownDocumentTarget): asserts target is ActionMarkdownTarget {
    if (target.document.kind !== 'action') throw new Error('Action Markdown source requires an action document')
}

function sectionMarkdown(
    definition: RawActionDefinition,
    section: ActionMarkdownSection,
    document: import('../../services/open_files_service').ActionOpenDocument,
) {
    if (section.kind === 'prompt') return definition.prompt ?? ''
    const phrase = requirePhrase(definition, section, document)
    return phrase.phrase.text
}

function requirePhrase(
    definition: RawActionDefinition,
    section: ActionMarkdownSection,
    document: import('../../services/open_files_service').ActionOpenDocument,
) {
    if (section.kind !== 'phrase') throw new Error(`Expected action phrase section: ${document.path}`)
    const phraseIndex = document.getObject().editorState?.phrases
        .findIndex(({ identity }) => identity === section.identity) ?? -1
    const phrase = definition.phrases?.[phraseIndex]
    if (phraseIndex < 0 || !phrase) throw new Error(`Unknown action phrase section: ${section.identity}`)

    return { phrase, phraseIndex }
}

function updatedDefinition(target: ActionMarkdownTarget, markdown: string) {
    const definition = target.document.getDraft()
    if (target.section.kind === 'prompt') return { ...definition, prompt: markdown }
    const { phraseIndex } = requirePhrase(definition, target.section, target.document)
    const phrases = definition.phrases ?? []
    return {
        ...definition,
        phrases: phrases.map((phrase, index) => index === phraseIndex ? { ...phrase, text: markdown } : phrase),
    }
}

function readActionMarkdown(target: MarkdownDocumentTarget) {
    actionTarget(target)
    return sectionMarkdown(target.document.getDraft(), target.section, target.document)
}

/** Reads and writes prompt/phrase sections through one canonical action document. */
export class ActionMarkdownDataSource extends MarkdownDataSourceBase {
    private service: ActionMarkdownOwner | null = null

    init(service: ActionMarkdownOwner) {
        if (this.service) return
        this.service = service
        openFilesService.addEventListener('documentChanged', this.handleDocumentChanged)
    }

    readonly getMarkdown = readActionMarkdown

    setActiveActionTarget(target: MarkdownDocumentTarget | null, discard = false) {
        if (target) actionTarget(target)
        this.setActiveTarget('list-action', target, discard)
    }

    edit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
        ActionMarkdownDataSource.requireActionBinding(binding)
        actionTarget(target)
        try {
            const definition = updatedDefinition(target, markdown)
            target.document.updateDraft(definition, binding)
            this.requireService().draftStore.stageDraft(target.document.path, definition)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Action update failed: ${target.document.path}` })
        }
    }

    commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
        ActionMarkdownDataSource.requireActionBinding(binding)
        actionTarget(target)
        try {
            const definition = updatedDefinition(target, markdown)
            target.document.updateDraft(definition, binding)
            this.requireService().draftStore.stageDraft(target.document.path, definition)
            if (target.section.kind === 'phrase') this.updatePhraseEditorState(target, definition)
            this.requireService().draftStore.commitDraft(target.document.path)
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Action update failed: ${target.document.path}` })
            return false
        }
    }

    private updatePhraseEditorState(
        target: ActionMarkdownTarget,
        definition: RawActionDefinition,
    ) {
        if (target.section.kind !== 'phrase') return
        const action = target.document.getObject()
        const editorState = action.editorState
        if (!editorState) throw new Error(`Missing phrase editor state for action: ${action.id}`)
        const { phraseIndex } = requirePhrase(definition, target.section, target.document)
        const phrases = definition.phrases ?? []
        const nextEditorState: ActionEditorState = {
            ...editorState,
            phrases: editorState.phrases.map((entry, index) => (
                index === phraseIndex ? { ...entry, phrase: phrases[index] } : entry
            )),
        }
        this.requireService().setActionEditorState(target.document.path, nextEditorState)
    }

    private readonly handleDocumentChanged = (event: Event) => {
        const { document, origin, type } = (event as CustomEvent<OpenDocumentChangedDetail>).detail
        if (document.kind !== 'action' || type !== 'draft') return
        const target = this.getActiveTarget('list-action')
        if (!target || target.document !== document) return

        const originBinding = typeof origin === 'string' ? origin as MarkdownBindingKind : null
        this.dispatchMarkdownReplaced({ originBinding, target })
    }

    private static requireActionBinding(binding: MarkdownBindingKind) {
        if (binding !== 'list-action') throw new Error(`Action Markdown source cannot use ${binding} binding`)
    }

    private requireService() {
        if (!this.service) throw new Error('Action Markdown data source is not initialized')
        return this.service
    }
}

export const actionMarkdownDataSource = new ActionMarkdownDataSource()

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import { useEffect, useLayoutEffect } from 'react'
import { useDialogError } from '../hooks/use_dialog_error'
import {
    markdownDocumentHistoryConfig$,
    markdownDocumentHistoryStore$,
} from './markdown_document_history_cell'
import { MarkdownDocumentHistoryMonitor } from './markdown_document_history_monitor'

/** Registers the card-scoped history store with MDXEditor's root Lexical editor. */
export function MarkdownDocumentHistoryPlugin() {
    const config = useCellValue(markdownDocumentHistoryConfig$)
    const historyStore = useCellValue(markdownDocumentHistoryStore$)
    const [editor] = useLexicalComposerContext()
    const historyStoreError = historyStore ? null : new Error('Cannot register Markdown history without a history store')
    useDialogError(historyStoreError, 'Markdown history is unavailable')

    useLayoutEffect(() => {
        if (!config || !historyStore) return

        historyStore.attachEditor(editor, config.initialTarget, config.initialMarkdown)

        return () => historyStore.detachEditor(editor)
    }, [config, editor, historyStore])

    useEffect(() => {
        if (!historyStore) return

        const unregister = historyStore.registerEditorHistory(editor)

        return unregister
    }, [editor, historyStore])

    return historyStore ? <MarkdownDocumentHistoryMonitor /> : null
}

import { useCellValue } from '@mdxeditor/editor'
import { useEffect } from 'react'
import { useDialogError } from '../hooks/use_dialog_error'
import { markdownDocumentHistoryConfig$ } from './markdown_document_history_cell'
import {
    sameMarkdownTarget,
    type ActiveMarkdownDocumentChangedDetail,
    type MarkdownReplacedDetail,
} from './markdown_data_source'

/** Keeps one editor's content and document history synchronized with its data-source binding. */
export function MarkdownDocumentHistoryMonitor() {
    const config = useCellValue(markdownDocumentHistoryConfig$)
    const configurationError = config ? null : new Error('Cannot monitor Markdown history without configuration')
    useDialogError(configurationError, 'Markdown history monitoring is unavailable')

    useEffect(() => {
        if (!config) return

        const {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        } = config
        let pendingDocumentChange: ActiveMarkdownDocumentChangedDetail | null = null

        const applyPendingDocumentChange = () => {
            const detail = pendingDocumentChange
            if (!detail) return

            const markdown = detail.target ? dataSource.getMarkdown(detail.target) : ''
            const currentMarkdown = prepareDocumentSwitch(detail, markdown)
            if (currentMarkdown === null) return

            pendingDocumentChange = null
            historyStore.switchDocument(detail.target, markdown, currentMarkdown, replaceMarkdown)
            completeDocumentSwitch(markdown)
        }
        const handleActiveDocumentChanged = (event: Event) => {
            const detail = (event as CustomEvent<ActiveMarkdownDocumentChangedDetail>).detail
            if (detail.binding !== binding) return

            pendingDocumentChange = detail
            applyPendingDocumentChange()
        }
        const reconcileActiveDocument = () => {
            const target = dataSource.getActiveTarget(binding)
            if (sameMarkdownTarget(target, getTarget())) return
            if (!pendingDocumentChange || !sameMarkdownTarget(pendingDocumentChange.target, target)) {
                pendingDocumentChange = { binding, target }
            }
            applyPendingDocumentChange()
        }
        const handleMarkdownReplaced = (event: Event) => {
            const detail = (event as CustomEvent<MarkdownReplacedDetail>).detail
            if (!sameMarkdownTarget(detail.target, getTarget()) || detail.originBinding === binding) return

            const markdown = dataSource.getMarkdown(detail.target)
            replaceMarkdown(markdown)
            historyStore.replaceDocument(detail.target, markdown)
            completeDocumentSwitch(markdown)
        }
        dataSource.addEventListener('activeDocumentChanged', handleActiveDocumentChanged)
        dataSource.addEventListener('markdownReplaced', handleMarkdownReplaced)
        setPendingDocumentChangeRetry(applyPendingDocumentChange)
        reconcileActiveDocument()

        return () => {
            setPendingDocumentChangeRetry(() => undefined)
            dataSource.removeEventListener('activeDocumentChanged', handleActiveDocumentChanged)
            dataSource.removeEventListener('markdownReplaced', handleMarkdownReplaced)
        }
    }, [config])

    return null
}

import type { ActionOpenDocument, CardOpenDocument, OpenDocument } from '../../services/open_files_service'

export type MarkdownBindingKind = 'board-card' | 'list-action' | 'list-card'

export type ActionMarkdownSection =
    | { kind: 'prompt' }
    | { kind: 'phrase', identity: string }

export type MarkdownDocumentTarget =
    | { document: ActionOpenDocument, section: ActionMarkdownSection }
    | { document: CardOpenDocument, section?: never }

export interface ActiveMarkdownDocumentChangedDetail {
    binding: MarkdownBindingKind
    /** Drop outgoing buffer because owning domain data was explicitly discarded. */
    discard?: boolean
    target: MarkdownDocumentTarget | null
}

export interface MarkdownReplacedDetail {
    originBinding: MarkdownBindingKind | null
    target: MarkdownDocumentTarget
}

export interface MarkdownBindingsSnapshot {
    activeBoardCardTarget: MarkdownDocumentTarget | null
    activeListActionTarget: MarkdownDocumentTarget | null
    activeListCardTarget: MarkdownDocumentTarget | null
}

export interface MarkdownDataSource extends EventTarget {
    commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): boolean
    edit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): void
    getActiveTarget(binding: MarkdownBindingKind): MarkdownDocumentTarget | null
    getMarkdown(target: MarkdownDocumentTarget): string
}

const INITIAL_BINDINGS: MarkdownBindingsSnapshot = {
    activeBoardCardTarget: null,
    activeListActionTarget: null,
    activeListCardTarget: null,
}

function bindingSnapshotKey(binding: MarkdownBindingKind): keyof MarkdownBindingsSnapshot {
    if (binding === 'board-card') return 'activeBoardCardTarget'
    if (binding === 'list-card') return 'activeListCardTarget'

    return 'activeListActionTarget'
}

export function sameMarkdownTarget(first: MarkdownDocumentTarget | null, second: MarkdownDocumentTarget | null) {
    if (first?.document !== second?.document) return false
    if (!first || !second) return true
    if (!first.section && !second.section) return true
    if (!first.section || !second.section) return false
    if (first.section.kind !== second.section.kind) return false

    return first.section.kind === 'prompt'
        || (second.section.kind === 'phrase' && first.section.identity === second.section.identity)
}

export function markdownTargetDocument(target: MarkdownDocumentTarget): OpenDocument {
    return target.document
}

/** Shared active-target and event behavior for Markdown sources. */
export abstract class MarkdownDataSourceBase extends EventTarget implements MarkdownDataSource {
    private bindings = INITIAL_BINDINGS

    abstract commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): boolean
    abstract edit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): void
    abstract getMarkdown(target: MarkdownDocumentTarget): string

    getBindingsSnapshot() {
        return this.bindings
    }

    getActiveTarget(binding: MarkdownBindingKind) {
        return this.bindings[bindingSnapshotKey(binding)]
    }

    setActiveTarget(binding: MarkdownBindingKind, target: MarkdownDocumentTarget | null, discard = false) {
        const key = bindingSnapshotKey(binding)
        if (sameMarkdownTarget(this.bindings[key], target)) return

        this.bindings = { ...this.bindings, [key]: target }
        const detail: ActiveMarkdownDocumentChangedDetail = { binding, discard, target }
        this.dispatchEvent(new CustomEvent('activeDocumentChanged', { detail }))
    }

    clearBindings(discard = false) {
        for (const binding of ['board-card', 'list-card', 'list-action'] as const) this.setActiveTarget(binding, null, discard)
    }

    protected dispatchMarkdownReplaced(detail: MarkdownReplacedDetail) {
        this.dispatchEvent(new CustomEvent('markdownReplaced', { detail }))
    }
}

