import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import { openFilesService, type OpenDocumentEventDetail } from '../../../services/open_files_service'
import { actionMarkdownDataSource } from '../../editor/action_markdown_data_source'
import { sameMarkdownTarget, type MarkdownDocumentTarget } from '../../editor/markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../../editor/markdown_document_history_store'
import { MarkdownEditor } from '../../editor/markdown_editor'
import { ActionEditor, type ActionMarkdownPresentation } from './action_editor'
import { useOpenFiles } from '../../hooks/use_open_files'
import { actionService } from '../../../services/actions/action_service'
import { useRetainedActionDocument } from './use_retained_action_document'
import { useProjectReadOnly } from '../../hooks/use_project_read_only'

interface ListActionEditorProps {
    cardTypes: string[]
    specialContextTypes: string[]
    states: string[]
}

/** Lifetime-stable list action editor surface and binding-owned undo store. */
export const ListActionEditor = memo(function ListActionEditor(props: ListActionEditorProps) {
    const { cardTypes, specialContextTypes, states } = props
    const readOnly = useProjectReadOnly()
    const { activeDocument } = useOpenFiles()
    const activeActionDocument = activeDocument?.kind === 'action' ? activeDocument : null
    const retainedActionDocument = useRetainedActionDocument()
    const retainedAction = retainedActionDocument?.getObject() ?? null
    const retainedPath = retainedAction?.sourcePath
    const actionExists = !!retainedPath && (
        !!actionService.getActionByPath(retainedPath)
        || actionService.draftStore.getDeletedDraftActions().some((candidate) => candidate.sourcePath === retainedPath)
    )
    const action = actionExists ? retainedAction : null
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const [presentation, setPresentation] = useState<ActionMarkdownPresentation | null>(null)

    const discardMarkdownTarget = useCallback((target: MarkdownDocumentTarget) => {
        historyStore.discardTarget(target)
        const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
        if (sameMarkdownTarget(activeTarget, target)) actionMarkdownDataSource.setActiveActionTarget(null, true)
    }, [historyStore])

    useEffect(() => {
        const handleRemoved = (event: Event) => {
            const { document } = (event as CustomEvent<OpenDocumentEventDetail>).detail
            if (document.kind !== 'action') return

            historyStore.discardDocument(document)
            const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
            if (activeTarget?.document === document) {
                actionMarkdownDataSource.setActiveActionTarget(null)
                setPresentation(null)
            }
        }
        openFilesService.addEventListener('removed', handleRemoved)

        return () => openFilesService.removeEventListener('removed', handleRemoved)
    }, [historyStore])

    useEffect(() => () => actionMarkdownDataSource.setActiveActionTarget(null), [])

    return (
        <Box
            data-testid="list-action-editor"
            hidden={!activeActionDocument}
            sx={{ display: activeActionDocument ? 'contents' : 'none' }}
        >
            {action && retainedActionDocument ? (
                <ActionEditor
                    actionDocument={retainedActionDocument}
                    cardTypes={cardTypes}
                    discardMarkdownTarget={discardMarkdownTarget}
                    onMarkdownPresentationChange={setPresentation}
                    specialContextTypes={specialContextTypes}
                    states={states}
                />
            ) : null}
            <Box hidden={!presentation} sx={{ flex: 1, minHeight: 0, order: 1, overflowY: 'auto' }}>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={actionMarkdownDataSource}
                    flushOnBlur
                    historyStore={historyStore}
                    placeholders={presentation?.placeholders}
                    readOnly={readOnly}
                    toolbarContents={readOnly ? undefined : presentation?.toolbarContents}
                />
            </Box>
        </Box>
    )
})

import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { ListCardCommitDiffPanel } from '../card_view/list_card_commit_diff_panel'
import { cardMarkdownDataSource, type CardDocumentClosedDetail } from '../editor/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { MarkdownEditor } from '../editor/markdown_editor'
import { ListEditorToolbarControls } from './list_editor_toolbar_controls'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { attachFilesToCardMarkdown } from '../../services/attachments/attachment_workflow'

interface CardEditorProps {
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

/** Lifetime-stable list-card editor with private history. */
export const CardEditor = memo(function CardEditor(props: CardEditorProps) {
    const { cardTypes, statusColors } = props
    const readOnly = useProjectReadOnly()
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => cardMarkdownDataSource.pasteImage('list-card', file, insertMarkdown),
        [],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = cardMarkdownDataSource.getActiveCard('list-card')
        if (!card) throw new Error('Cannot attach files without an active list card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [])

    useEffect(() => {
        const handleCardDocumentClosed = (event: Event) => {
            const { binding, document } = (event as CustomEvent<CardDocumentClosedDetail>).detail
            if (binding !== 'list-card') return

            historyStore.discardDocument(document)
        }
        cardMarkdownDataSource.addEventListener('cardDocumentClosed', handleCardDocumentClosed)

        return () => {
            cardMarkdownDataSource.removeEventListener('cardDocumentClosed', handleCardDocumentClosed)
        }
    }, [historyStore])

    const toolbarContents = useCallback(() => (
        <ListEditorToolbarControls
            cardTypes={cardTypes}
            historyStore={historyStore}
            readOnly={readOnly}
            statusColors={statusColors}
        />
    ), [cardTypes, historyStore, readOnly, statusColors])

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}>
            <ListCardCommitDiffPanel>
                <MarkdownEditor
                    attachmentHandler={handleAttachments}
                    binding="list-card"
                    dataSource={cardMarkdownDataSource}
                    historyStore={historyStore}
                    imagePasteHandler={handleImagePaste}
                    readOnly={readOnly}
                    toolbarContents={toolbarContents}
                />
            </ListCardCommitDiffPanel>
        </Box>
    )
})

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { AppThemeProvider } from '../../theme/theme_provider'
import { DEFAULT_CARD_TYPES } from '../../data/data_types'
import { cardMarkdownDataSource } from '../editor/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import type { MarkdownDocumentTarget } from '../editor/markdown_data_source'
import { CardBodyEditor } from './card_body_editor'

function renderCardBodyEditor(props: Parameters<typeof CardBodyEditor>[0]) {
    return render(
        <AppThemeProvider>
            <CardBodyEditor {...props} />
        </AppThemeProvider>,
    )
}

function editorProps(overrides: Partial<Parameters<typeof CardBodyEditor>[0]> = {}): Parameters<typeof CardBodyEditor>[0] {
    return {
        cardTypes: DEFAULT_CARD_TYPES,
        dataSource: cardMarkdownDataSource,
        historyStore: new MarkdownDocumentHistoryStore(),
        isFullscreen: false,
        onToggleFullscreen: vi.fn(),
        statusColors: new Map(),
        ...overrides,
    }
}

describe('CardBodyEditor', () => {
    const target = { document: { kind: 'card' } } as MarkdownDocumentTarget

    beforeEach(() => {
        cardMarkdownDataSource.setActiveTarget('board-card', target)
        vi.spyOn(cardMarkdownDataSource, 'getMarkdown').mockReturnValue('# Alpha\n\nOriginal body')
        vi.spyOn(cardMarkdownDataSource, 'edit').mockImplementation(() => undefined)
        vi.spyOn(cardMarkdownDataSource, 'commit').mockReturnValue(true)
        vi.spyOn(cardMarkdownDataSource, 'getActiveCard').mockReturnValue(null)
    })

    afterEach(() => {
        cleanup()
        cardMarkdownDataSource.setActiveTarget('board-card', null)
        vi.restoreAllMocks()
    })

    it('loads body through board-card data source binding', () => {
        renderCardBodyEditor(editorProps())

        expect(screen.getByRole('textbox')).toHaveValue('# Alpha\n\nOriginal body')
        expect(screen.getByRole('button', { name: 'Attach files' })).toBeInTheDocument()
        expect(cardMarkdownDataSource.getMarkdown).toHaveBeenCalledWith(target)
    })

    it('commits outgoing document target when editor unmounts', () => {
        const { unmount } = renderCardBodyEditor(editorProps())
        fireEvent.change(screen.getByRole('textbox'), { target: { value: '# Alpha\n\nEdited body' } })

        unmount()

        expect(cardMarkdownDataSource.commit).toHaveBeenCalledWith('board-card', target, '# Alpha\n\nEdited body')
    })

    it.each([
        { isMobile: false, layout: 'desktop' },
        { isMobile: true, layout: 'mobile' },
    ])('keeps toolbar sticky on $layout', ({ isMobile }) => {
        const { container } = renderCardBodyEditor(editorProps({ isMobile }))

        expect(container.querySelector('[data-sticky-toolbar="true"]')).not.toBeNull()
    })

    it('hides fullscreen control on mobile', () => {
        renderCardBodyEditor(editorProps({ isMobile: true }))

        expect(screen.queryByRole('button', { name: 'Fullscreen' })).not.toBeInTheDocument()
    })

    it('keeps fullscreen control on desktop', () => {
        renderCardBodyEditor(editorProps())

        expect(screen.getByRole('button', { name: 'Fullscreen' })).toBeInTheDocument()
    })
})

